static HBITMAP qr_bitmap(const char *value){uint8_t scratch[qrcodegen_BUFFER_LEN_MAX],qr[qrcodegen_BUFFER_LEN_MAX];if(!qrcodegen_encodeText(value,scratch,qr,qrcodegen_Ecc_MEDIUM,1,qrcodegen_VERSION_MAX,qrcodegen_Mask_AUTO,true))return NULL;int modules=qrcodegen_getSize(qr),scale=224/(modules+8),size=(modules+8)*scale;BITMAPINFO info={0};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=size;info.bmiHeader.biHeight=-size;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;uint32_t *pixels=NULL;HBITMAP bitmap=CreateDIBSection(NULL,&info,DIB_RGB_COLORS,(void**)&pixels,NULL,0);if(!bitmap)return NULL;for(int y=0;y<size;y++)for(int x=0;x<size;x++){int qx=x/scale-4,qy=y/scale-4;pixels[y*size+x]=qx>=0&&qy>=0&&qx<modules&&qy<modules&&qrcodegen_getModule(qr,qx,qy)?0xff000000:0xffffffff;}return bitmap;}
